Creating a complex smart contract involves a deep understanding of blockchain technology, programming (typically in Solidity for Ethereum), and the specific requirements of the contract's intended use case. Below is a simplified example of a complex smart contract written in Solidity, which is a contract for a decentralized voting system. This is a conceptual example and not a production-ready contract.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract DecentralizedVoting {
    struct Voter {
        bool voted;  // if true, voter has already voted
        uint vote;   // index of the voted proposal
    }

    struct Proposal {
        bytes32 name;   // short name (up to 32 bytes)
        uint voteCount; // number of accumulated votes
    }

    address public chairperson;
    mapping(address => Voter) public voters;
    Proposal[] public proposals;

    // Create a new proposal
    constructor(bytes32[] memory proposalNames) {
        chairperson = msg.sender;
        for (uint i = 0; i < proposalNames.length; i++) {
            proposals.push(Proposal({
                name: proposalNames[i],
                voteCount: 0
            }));
        }
    }

    // Give a voter the right to vote on a proposal
    function giveRightToVote(address voter) public {
        require(
            msg.sender == chairperson,
            "Only the chairperson can give voting rights."
        );
        require(
            !voters[voter].voted,
            "The voter already voted."
        );
        voters[voter].voted = false;
    }

    // Delegate your vote to the voter right, voter must not have voted yet
    function delegate(address to) public {
        Voter storage sender = voters[msg.sender];
        require(!sender.voted, "You already voted.");

        require(to != msg.sender, "Self-delegation is disallowed.");

        // Forward the vote
        voters[to].vote = sender.vote;
    }

    // Vote for a proposal
    function vote(uint proposal) public {
        Voter storage sender = voters[msg.sender];
        require(!sender.voted, "Already voted.");
        require(sender.vote == 0, "No delegation found.");

        sender.voted = true;
        sender.vote = proposal;

        // If the proposal is the first one, increment the vote count
        if (proposal == 0) {
            proposals[0].voteCount += 1;
        }
    }

    // Compute the winning proposal taking all previous votes into account
    function winningProposal() public view
            returns (uint winningProposal_)
    {
        uint winningVoteCount = 0;
        for (uint p = 0; p < proposals.length; p++) {
            if (proposals[p].voteCount > winningVoteCount) {
                winningVoteCount = proposals[p].voteCount;
                winningProposal_ = p;
            }
        }
    }

    // Get the name of the winning proposal
    function winnerName() public view
            returns (bytes32 winnerName_)
    {
        winnerName_ = proposals[winningProposal()].name;
    }
}
```

This contract allows for the creation of a voting system where proposals can be voted on by a set of voters. The chairperson can give voting rights to voters, and voters can either vote directly or delegate their vote to another voter. The contract also includes functions to count votes and determine the winning proposal.

Please note that this is a simplified example for educational purposes. Real-world smart contracts require thorough testing, security audits, and consideration of various edge cases and potential vulnerabilities.

